'use strict';
(async()=>{const title=document.querySelector('#title'),message=document.querySelector('#message'),total=document.querySelector('#total');try{const id=new URLSearchParams(location.search).get('session_id');if(!id)throw Error('No checkout reference was provided.');const r=await fetch('/api/checkout-status?session_id='+encodeURIComponent(id),{cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error||'Unable to check payment.');if(d.paid){title.textContent='Test payment successful';message.textContent='Stripe confirmed your sandbox payment. No money was charged and no order will be shipped. Your test basket has been kept so you can test again.';total.textContent='Test total: '+new Intl.NumberFormat('en-IE',{style:'currency',currency:d.currency.toUpperCase()}).format(d.total/100)}else{title.textContent='Test payment not completed';message.textContent='Stripe has not confirmed a completed payment. You can return to your basket and try again.'}}catch(e){title.textContent='Unable to confirm test payment';message.textContent=e.message+' Your basket is still available.'}})();
